def build_track(track_id, title, rows, color, project=False):
    topics=[]
    for i,row in enumerate(rows,1):
        name,theory,pitfall,exercise,acceptance,extra=row
        topic_id=f"{track_id}-{i:02d}"
        minutes=extra if project else 20
        prompt=f"Ты наставник junior Python backend. Тема: {name}. Объясни простыми словами: {theory} Покажи конкретный пример на JobFlow и ошибку: {pitfall} Затем задай 3 вопроса по одному и разбери ответы. Практика ученика: {exercise} Не решай её за меня. Критерий: {acceptance} Не приписывай мне реальный командный опыт."
        tasks=[{"id":f"{topic_id}-p01","title":name+(' — этап проекта' if project else ' — объяснить и применить'),"kind":"code" if project else "practice","label":"ПРОЕКТ" if project else "ЛЁГКИЙ ТРЕК","statement":exercise,"description":exercise,"deliverable":acceptance,"example":theory,"difficulty":"medium" if project else "easy","minutes":minutes,"artifact":f"JobFlow/docs/{topic_id}.md","case":exercise}]
        if not project: tasks[0]["external_url"]=extra
        topics.append({"id":topic_id,"number":i,"title":name,"theory":theory,"pitfall":pitfall,"mastery":acceptance,"mentor_prompt":prompt,"practice_links":[],"tasks":tasks})
    return {"id":track_id,"number":12 if project else 11,"title":title,"color":color,"goal":"Один законченный backend с доказательствами и защитой" if project else "20 минут на тему: термин, пример, компромисс и ответ на собеседовании","topics":topics}

EXTRA_CAREER_TRACKS=[build_track("architecture","Архитектура и команда · легко",ARCHITECTURE,"#e6bd8a"),build_track("project","Проект JobFlow",PROJECT,"#8df5c7",True)]

